package com.bank.faulttolerance.cluster;

import com.bank.faulttolerance.model.HealthStatus;

public class ServiceInstance {
    private final String id;
    private final String zone;
    private HealthStatus status;

    public ServiceInstance(String id, String zone) {
        this.id = id;
        this.zone = zone;
        this.status = HealthStatus.STARTING;
    }
    public String getId() { return id; }
    public String getZone() { return zone; }
    public HealthStatus getStatus() { return status; }

    // Liveness: process alive? Readiness: ready for traffic?
    public boolean isLive() { return status != HealthStatus.CRASHED; }
    public boolean isReady() { return status == HealthStatus.READY; }

    public void markReady() { if (status == HealthStatus.STARTING) status = HealthStatus.READY; }
    public void crash() { status = HealthStatus.CRASHED; }
}
