package com.bank.faulttolerance.cluster;

import java.util.*;
import java.util.stream.Collectors;

// Holds instances and knows the desired replica count and available zones.
public class ServiceCluster {
    private final int desiredReplicas;
    private final List<String> zones;
    private final List<ServiceInstance> instances = new ArrayList<>();
    private int idSeq = 0;

    public ServiceCluster(int desiredReplicas, List<String> zones) {
        this.desiredReplicas = desiredReplicas;
        this.zones = zones;
    }

    public int getDesiredReplicas() { return desiredReplicas; }
    public List<ServiceInstance> getInstances() { return instances; }

    public List<ServiceInstance> liveInstances() {
        return instances.stream().filter(ServiceInstance::isLive).collect(Collectors.toList());
    }
    public List<ServiceInstance> readyInstances() {
        return instances.stream().filter(ServiceInstance::isReady).collect(Collectors.toList());
    }

    // Create a new instance in the least-populated zone (topology spread).
    public ServiceInstance addInstance() {
        Map<String, Long> perZone = liveInstances().stream()
                .collect(Collectors.groupingBy(ServiceInstance::getZone, Collectors.counting()));
        String target = zones.stream()
                .min(Comparator.comparingLong(z -> perZone.getOrDefault(z, 0L)))
                .orElse(zones.get(0));
        ServiceInstance inst = new ServiceInstance("txn-" + (++idSeq), target);
        instances.add(inst);
        return inst;
    }
}
