package com.bank.faulttolerance.cluster;

import java.util.List;
import java.util.logging.Logger;

// Mimics the Kubernetes self-healing control loop: drive live count to desired.
public class InstanceSupervisor {
    private static final Logger log = Logger.getLogger(InstanceSupervisor.class.getName());
    private final ServiceCluster cluster;

    public InstanceSupervisor(ServiceCluster cluster) { this.cluster = cluster; }

    // One reconcile tick: if live < desired, create replacements in spread zones.
    public void reconcile() {
        int live = cluster.liveInstances().size();
        int desired = cluster.getDesiredReplicas();
        if (live < desired) {
            int missing = desired - live;
            log.warning(() -> "SELF-HEAL live=" + live + " desired=" + desired
                    + " creating " + missing + " replacement(s)");
            for (int i = 0; i < missing; i++) {
                ServiceInstance inst = cluster.addInstance();
                log.info(() -> "CREATED " + inst.getId() + " in zone " + inst.getZone()
                        + " (STARTING, not yet ready)");
            }
        }
    }

    // Readiness gate: only ready instances receive traffic.
    public List<ServiceInstance> routable() { return cluster.readyInstances(); }
}
