package com.bank.faulttolerance;

import com.bank.faulttolerance.cluster.*;
import java.util.List;
import java.util.logging.*;

public class FaultToleranceDemo {
    public static void main(String[] args) {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());
        Logger log = Logger.getLogger(FaultToleranceDemo.class.getName());

        ServiceCluster cluster = new ServiceCluster(3, List.of("zone-a", "zone-b", "zone-c"));
        InstanceSupervisor supervisor = new InstanceSupervisor(cluster);

        // Start desired replicas across zones and warm them up.
        supervisor.reconcile();
        cluster.getInstances().forEach(ServiceInstance::markReady);
        log.info("Routable instances: " + cluster.readyInstances().size());

        // Crash TWO instances (e.g. a node failure).
        List<ServiceInstance> live = cluster.liveInstances();
        live.get(0).crash();
        live.get(1).crash();
        log.severe("Two instances crashed: " + live.get(0).getId()
                + " and " + live.get(1).getId());
        log.warning("Routable right now: " + cluster.readyInstances().size()
                + " (surviving instance absorbs traffic)");

        // Self-heal: supervisor recreates the lost capacity, spread across zones.
        supervisor.reconcile();

        // New instances start NOT ready — readiness gate keeps them out of rotation.
        log.info("Routable before warmup: " + cluster.readyInstances().size());
        cluster.getInstances().forEach(ServiceInstance::markReady);
        log.info("Routable after warmup: " + cluster.readyInstances().size()
                + " (back to desired=" + cluster.getDesiredReplicas() + ")");
    }
}

